{
  "requirement_id": "REQ-005",
  "cases": [
    {
      "id": "TC-1",
      "title": "Valid state transitions",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"in_progress\"} on a todo task",
        "POST /api/tasks/{tid}/transition with {\"to\": \"done\"} on an in_progress task",
        "POST /api/tasks/{tid}/transition with {\"to\": \"todo\"} on an in_progress task"
      ],
      "expected": "允許從 todo 流轉至 in_progress。允許從 in_progress 流轉至 done。允許從 in_progress 流轉至 todo。"
    },
    {
      "id": "TC-2",
      "title": "Transitions from done state",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"todo\"} on a done task",
        "POST /api/tasks/{tid}/transition with {\"to\": \"in_progress\"} on a done task",
        "POST /api/tasks/{tid}/transition with {\"to\": \"done\"} on a done task"
      ],
      "expected": "當任務狀態為 done 時，任何從 done 出發的流轉請求皆應回傳 409 且任務狀態保持不變。"
    },
    {
      "id": "TC-3",
      "title": "Unlisted transitions (todo to done and self-transitions)",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"done\"} on a todo task",
        "POST /api/tasks/{tid}/transition with {\"to\": \"todo\"} on a todo task",
        "POST /api/tasks/{tid}/transition with {\"to\": \"in_progress\"} on an in_progress task"
      ],
      "expected": "未列出的流轉（包含 todo → done 以及相同狀態的流轉）皆應回傳 409。"
    },
    {
      "id": "TC-4",
      "title": "Invalid status parameter in transition request",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"invalid_status\"}"
      ],
      "expected": "當請求中的 to 參數不是合法的狀態（非 todo、in_progress、done）時，應回傳 422。"
    }
  ]
}

